-- ==============================================================================
-- FEEDER AKUN PENGGUNA (ADMIN OPD) KE DATABASE USUL DATA
-- UPSERT: Jika username sudah ada, perbarui password_hash, role, dan kode_unor.
-- Format kode_unor: 10 digit (skema SIMPEG Trenggalek - kode 2 digit + 00000000)
-- ==============================================================================

ON DUPLICATE KEY UPDATE
  `password_hash` = VALUES(`password_hash`),
  `role` = VALUES(`role`),
  `kode_unor` = VALUES(`kode_unor`),
  `updated_at` = NOW();
